//! Dictionary-dependent blocks made with the permitted oracle surface only.

use crate::block::decompress_safe;
use crate::frame::{compress_frame, Prefs};

/// The size of the largest block (block size id 7).
const MAX_BLOCK: usize = 4 << 20;

/// A compressed block and whether it needs the dictionary to decode.
#[derive(Debug, Clone)]
pub struct DictBlock {
    pub block: Vec<u8>,
    pub dict_dependent: bool,
}

fn le32(b: &[u8], at: usize) -> Option<u32> {
    let s = b.get(at..at.checked_add(4)?)?;
    Some(u32::from_le_bytes([s[0], s[1], s[2], s[3]]))
}

/// Compress `data` as the second linked block of a frame whose first block
/// came from `dict` (Frame format, "Block Independence flag": linked blocks
/// may refer to earlier blocks). The frame is walked by the Frame format's
/// "Data Blocks" layout: a 7-byte header, then 4-byte little-endian block
/// sizes whose top bit marks an uncompressed block. Returns the second block,
/// or `None` when it was stored uncompressed.
pub fn dict_block(dict: &[u8], data: &[u8]) -> Option<DictBlock> {
    assert!(dict.len() <= MAX_BLOCK && data.len() <= MAX_BLOCK);
    let prefs = Prefs {
        block_size_id: 7,
        linked: true,
        auto_flush: true,
        ..Prefs::default()
    };
    let frame = compress_frame(&[dict, data], &prefs);
    let mut pos = 7usize;
    let mut blocks: Vec<(bool, &[u8])> = Vec::new();
    loop {
        let word = le32(&frame, pos)?;
        if word == 0 {
            break;
        }
        let uncompressed = word & 0x8000_0000 != 0;
        let len = (word & 0x7FFF_FFFF) as usize;
        let start = pos + 4;
        let bytes = frame.get(start..start.checked_add(len)?)?;
        blocks.push((uncompressed, bytes));
        pos = start + len;
    }
    // One block per chunk was requested; anything else is not what we can use.
    if blocks.len() != 2 {
        return None;
    }
    let (uncompressed, bytes) = blocks[1];
    if uncompressed {
        return None;
    }
    let plain = decompress_safe(bytes, data.len() + 65_536);
    let dict_dependent = !matches!(&plain, Ok(v) if v == data);
    Some(DictBlock {
        block: bytes.to_vec(),
        dict_dependent,
    })
}
